-- Seed gerado por assets/gerador-avaliacao-discursiva (não editar à mão; fora do Git).
-- Rodar depois de database/2026-10-01-respostas-discursivas.sql. Idempotente.
-- A avaliação nasce BLOQUEADA (ativo = false): o professor libera no índice de atividades.
do $$
declare
  v_aula bigint;
  v_atividade bigint;
begin
  select a.id into v_aula from public.aulas a join public.materia m on m.id = a.materia_id
    where m.descricao = 'Fundamentos de UI / UX' and a.numero = 19
    order by a.id limit 1;
  if v_aula is null then
    raise exception 'Aula 19 da matéria não encontrada';
  end if;

  insert into public.atividade (nome_atividade, status, aula_id, descricao, pagina,
      total_itens, ativo)
    values ('Atividade Prática — Aula 19', 'PENDENTE', v_aula, 'Atividade — Atividade Prática — Aula 19 (20 questões discursivas)',
      '/MATERIAIS/TECNICO-INFORMATICA-INTERNET/FUNDAMENTOS-DE-UI-UX/ATIVIDADES/ATIVIDADE-PRATICA-AULA-19.html', 20, false)
    on conflict (pagina) do update set aula_id = excluded.aula_id,
      descricao = excluded.descricao, total_itens = excluded.total_itens
    returning id into v_atividade;

  delete from public.topico_discursivo where atividade_id = v_atividade;
  insert into public.topico_discursivo (atividade_id, item, topico, enunciado, pontos,
      resposta_esperada, criterios) values
      (v_atividade, 1, 1, 'Defina direito autoral com suas palavras.', 0.2, 'Direito autoral é o conjunto de direitos jurídicos concedidos ao criador sobre sua obra intelectual ou artística (ilustrações, textos, fotos e interfaces).', 'Nota cheia: define direito autoral como direito do criador sobre a obra, com as palavras do aluno. Metade: cita apenas que é uma proteção para quem cria, sem relação com a obra. Zero: em branco, errado ou copiado.'),
      (v_atividade, 1, 2, 'Diga em que momento, segundo a aula, a interface passa a ser protegida e qual lei brasileira é citada.', 0.4, 'A interface passa a ser protegida no momento da criação original (rascunho ou editor vetorial), segundo a Lei nº 9.610/1998.', 'Nota cheia: indica o momento da criação e cita a Lei nº 9.610/1998. Metade: indica o momento da criação, mas não cita a lei, ou cita a lei sem o momento correto. Zero: diz que a proteção depende de registro ou de publicação, ou está em branco.'),
      (v_atividade, 1, 3, 'Explique a diferença entre a proteção, que começa com a criação, e o registro, que serve para formalizar a prova.', 0.4, 'A proteção nasce com a criação; o registro em órgão oficial serve para formalizar a prova de titularidade, não para criar o direito.', 'Nota cheia: separa as duas coisas (proteção começa na criação; registro formaliza a prova). Metade: explica só um dos dois lados ou confunde os papéis sem negar a proteção pela criação. Zero: diz que só o registro protege a obra, ou está em branco.'),
      (v_atividade, 2, 1, 'Cite o que são os direitos morais.', 0.2, 'Direitos morais garantem o reconhecimento eterno de quem criou a obra, ligado à autoria.', 'Nota cheia: define direitos morais como o reconhecimento da autoria, com as palavras do aluno. Metade: cita apenas que é o direito de ter o nome citado, sem a ideia de autoria. Zero: em branco, errado ou copiado.'),
      (v_atividade, 2, 2, 'Explique por que, segundo a aula, os direitos morais não podem ser vendidos nem removidos.', 0.4, 'Os direitos morais são inalienáveis e irrenunciáveis: ninguém pode comprar a autoria nem remover o nome do criador da obra.', 'Nota cheia: cita que são inalienáveis e irrenunciáveis (ou equivalente) e que não se vendem nem se removem. Metade: diz que não podem ser removidos, sem explicar que não se vendem. Zero: diz que podem ser vendidos ou removidos, ou está em branco.'),
      (v_atividade, 2, 3, 'Explique o que o autor pode fazer com os direitos patrimoniais, citando pelo menos duas ações.', 0.4, 'Os direitos patrimoniais permitem ao autor ceder, vender ou licenciar a reprodução, a distribuição e a adaptação da criação para aplicativos e sites.', 'Nota cheia: cita pelo menos duas ações (ex.: reproduzir, distribuir, adaptar, vender, licenciar) ligadas à exploração econômica. Metade: cita apenas uma ação ou fala de exploração sem exemplos. Zero: em branco ou não relaciona aos direitos patrimoniais.'),
      (v_atividade, 3, 1, 'Nomeie as três etapas da linha de proteção da obra.', 0.2, 'As três etapas são criação, fixação e publicação.', 'Nota cheia: nomeia as três etapas na ordem. Metade: nomeia duas etapas corretas. Zero: nomeia etapas que não estão na aula ou está em branco.'),
      (v_atividade, 3, 2, 'Explique o que acontece na fixação e para que serve o registro com data e hora.', 0.4, 'A fixação salva a obra em suporte físico ou repositório com data e hora (timestamp); o registro com data e hora serve de prova da existência da obra naquela data.', 'Nota cheia: explica a fixação (salvar com timestamp) e diz que o registro com data prova a existência em certo momento. Metade: explica só a fixação ou só a prova, sem conectar as duas. Zero: em branco ou errado.'),
      (v_atividade, 3, 3, 'Explique o que significa publicar a obra sob termos de licença.', 0.4, 'Publicar é o lançamento oficial da obra ao público, sob os termos de uma licença que define o uso permitido.', 'Nota cheia: diz que publicar é o lançamento ao público e que vem com termos de licença. Metade: diz só que é lançar a obra, sem citar a licença. Zero: em branco ou errado.'),
      (v_atividade, 4, 1, 'Explique o princípio da anterioridade.', 0.2, 'O princípio da anterioridade diz que vence quem comprovar que a sua criação existia primeiro, por meio de registros confiáveis, datas, commits ou depósitos.', 'Nota cheia: diz que vence quem prova a criação primeiro, com as palavras do aluno. Metade: diz só que é ser o primeiro, sem falar em prova. Zero: em branco ou errado.'),
      (v_atividade, 4, 2, 'Liste três tipos de prova de anterioridade citados na aula.', 0.4, 'Três entre: registros cronológicos confiáveis, datas de arquivos, commits de código, depósitos formais (ou rascunhos datados em papel).', 'Nota cheia: lista três tipos corretos. Metade: lista um ou dois tipos corretos. Zero: lista tipos que não estão na aula, ou está em branco.'),
      (v_atividade, 4, 3, 'Explique por que guardar rascunhos datados e o histórico de versões ajuda na defesa profissional.', 0.4, 'Rascunhos datados e o histórico de versões funcionam como evidência cronológica de que a criação existia antes de cópias, o que fortalece a defesa profissional.', 'Nota cheia: liga rascunhos e histórico de versões à evidência de anterioridade e à defesa. Metade: diz que são úteis, sem explicar a prova cronológica. Zero: em branco ou errado.'),
      (v_atividade, 5, 1, 'Responda se o acesso público a uma imagem autoriza o uso livre, justificando.', 0.2, 'Não. O acesso público não autoriza o uso livre; a imagem continua protegida por direito autoral.', 'Nota cheia: responde "não" e justifica que estar publicado não dá permissão de uso. Metade: responde "não" sem justificativa, ou justifica com ideia parcial. Zero: responde "sim" ou está em branco.'),
      (v_atividade, 5, 2, 'Cite três riscos do uso indevido de recursos mencionados na aula.', 0.4, 'Três entre: infração de direito autoral, infração de direito de imagem, multas pesadas (no caso de fontes), revenda ou citação de autoria não atendidas, banimento do app na loja, dano à reputação.', 'Nota cheia: cita três riscos corretos da aula. Metade: cita um ou dois riscos corretos. Zero: cita riscos fora da aula ou está em branco.'),
      (v_atividade, 5, 3, 'Explique a consequência de uma notificação extrajudicial e o prazo citado na aula.', 0.4, 'A notificação extrajudicial exige a retirada imediata do ar em até 48 horas.', 'Nota cheia: explica a notificação e cita o prazo de 48 horas para retirar o recurso do ar. Metade: explica a notificação sem o prazo, ou cita o prazo sem a notificação. Zero: em branco ou errado.'),
      (v_atividade, 6, 1, 'Diga quais são as duas formas de infração citadas para fotos sem autorização.', 0.2, 'Duas formas de infração: infração de direito de imagem e infração de direito autoral.', 'Nota cheia: cita as duas formas. Metade: cita apenas uma forma correta. Zero: em branco ou errado.'),
      (v_atividade, 6, 2, 'Explique por que a autorização do fotógrafo e da pessoa retratada são necessárias.', 0.4, 'A autorização do fotógrafo é necessária porque ele é o autor da foto (direito autoral); a da pessoa retratada é necessária por causa do direito de imagem.', 'Nota cheia: explica as duas autorizações, cada uma com sua razão. Metade: explica só uma das duas. Zero: em branco ou errado.'),
      (v_atividade, 6, 3, 'Relacione essa situação ao risco de dano à reputação do cliente.', 0.4, 'Usar a foto sem autorização pode causar infração e fazer o cliente perder a confiança na consultoria, com risco de o aplicativo ser banido das lojas.', 'Nota cheia: relaciona o uso indevido à perda de confiança do cliente e ao dano à reputação. Metade: cita o dano sem ligar ao cliente. Zero: em branco ou fora do tema.'),
      (v_atividade, 7, 1, 'Diga por que as fontes são tratadas como software protegido.', 0.2, 'Porque as fontes são softwares protegidos por direito autoral.', 'Nota cheia: diz que a fonte é software protegido (com as palavras do aluno). Metade: diz que é protegida, sem citar que é software. Zero: em branco ou errado.'),
      (v_atividade, 7, 2, 'Explique o que deve ser conferido antes de incorporar um arquivo de fonte em um aplicativo.', 0.4, 'Conferir a licença do arquivo (o EULA) e se ela autoriza o uso em webfont ou em app, especialmente em app vendido (licença comercial).', 'Nota cheia: cita a licença (EULA) e a permissão para webfont ou app, com foco no uso comercial. Metade: cita só a licença, sem o uso no app. Zero: em branco ou errado.'),
      (v_atividade, 7, 3, 'Descreva as duas primeiras etapas do procedimento de checagem de fontes.', 0.4, 'Primeira etapa: ler o EULA (abrir o arquivo de licença de usuário). Segunda etapa: ver a permissão (conferir se a licença autoriza webfont ou app).', 'Nota cheia: descreve as duas etapas na ordem. Metade: descreve uma etapa corretamente. Zero: em branco ou errado.'),
      (v_atividade, 8, 1, 'Diga o que a aula afirma sobre pacotes de ícones quanto à citação de autoria.', 0.2, 'Pacotes de ícones podem exigir citação pública de autoria, por exemplo no rodapé do aplicativo.', 'Nota cheia: diz que a aula exige citação pública de autoria. Metade: diz que há exigência de autoria, sem citar a citação pública. Zero: em branco ou errado.'),
      (v_atividade, 8, 2, 'Explique o que significa a proibição de revenda comercial direta.', 0.4, 'Significa que não se pode vender o pacote de ícones diretamente como produto, ou seja, revender a obra em si.', 'Nota cheia: explica que não se pode revender o recurso em si, sem negócio direto com o ícone. Metade: explica de forma vaga (ex.: "não pode vender"), sem o sentido de revenda direta. Zero: em branco ou errado.'),
      (v_atividade, 8, 3, 'Explique onde e como a citação de autoria deve aparecer no aplicativo.', 0.4, 'A citação deve aparecer publicamente no aplicativo, por exemplo no rodapé ou na tela de créditos, com o nome do autor e o link da licença.', 'Nota cheia: indica o local (rodapé ou tela de créditos) e o conteúdo (autor e link). Metade: indica o local sem o conteúdo, ou o contrário. Zero: em branco ou errado.'),
      (v_atividade, 9, 1, 'Cite a consequência de suspensão da plataforma.', 0.2, 'Suspensão da plataforma: as lojas digitais, como Google Play e App Store, desativam o aplicativo por violação dos termos.', 'Nota cheia: cita a suspensão do app pela loja por violação dos termos. Metade: cita a suspensão sem a causa. Zero: em branco ou errado.'),
      (v_atividade, 9, 2, 'Explique o que é indenização financeira e o que ela cobre.', 0.4, 'Indenização financeira é o pagamento retroativo de perdas e danos pelo uso não autorizado do patrimônio alheio.', 'Nota cheia: define como pagamento de perdas e danos pelo uso não autorizado. Metade: diz só que é uma multa ou pagamento, sem o uso não autorizado. Zero: em branco ou errado.'),
      (v_atividade, 9, 3, 'Explique por que o dano à reputação pode afetar a confiança na consultoria de design.', 0.4, 'O dano à reputação faz o cliente perder a confiança na consultoria de design, o que prejudica o trabalho futuro do aluno consultor.', 'Nota cheia: relaciona a reputação à perda de confiança na consultoria. Metade: cita o dano à reputação sem ligar à consultoria. Zero: em branco ou fora do tema.'),
      (v_atividade, 10, 1, 'Defina Creative Commons e diferencie-o do modelo "todos os direitos reservados".', 0.2, 'Creative Commons é uma organização global que oferece licenças prévias para criadores; ao contrário de "todos os direitos reservados", adota "alguns direitos reservados".', 'Nota cheia: define o CC e faz a diferença com "todos os direitos reservados". Metade: define o CC sem a diferença. Zero: em branco ou errado.'),
      (v_atividade, 10, 2, 'Explique o significado do lema "alguns direitos reservados".', 0.4, 'O lema "alguns direitos reservados" significa que o criador reserva certos direitos e libera outros, definidos claramente na licença.', 'Nota cheia: explica que alguns direitos são reservados e outros liberados pela licença. Metade: explica de forma vaga, sem a ideia de liberação parcial. Zero: em branco ou errado.'),
      (v_atividade, 10, 3, 'Explique por que as licenças CC permitem o uso sem contato individual com o criador.', 0.4, 'Porque a licença define antecipadamente o que é permitido, então ninguém precisa pedir autorização individual ao criador.', 'Nota cheia: liga a licença prévia e clara à dispensa de contato individual. Metade: diz só que a licença facilita, sem explicar o motivo. Zero: em branco ou errado.'),
      (v_atividade, 11, 1, 'Explique o que exige o bloco BY.', 0.2, 'BY (Atribuição) exige citar o nome do criador original e fornecer o link para a licença.', 'Nota cheia: diz que exige citar o criador e fornecer o link da licença. Metade: diz só "dar crédito", sem o link. Zero: em branco ou errado.'),
      (v_atividade, 11, 2, 'Explique o que o bloco NC proíbe.', 0.4, 'NC (Não Comercial) proíbe usar a obra para obter lucro direto ou benefício econômico.', 'Nota cheia: diz que proíbe lucro direto ou benefício econômico. Metade: diz só "não pode usar para vender", sem ampliar para benefício econômico. Zero: em branco ou errado.'),
      (v_atividade, 11, 3, 'Explique o que o bloco ND permite e o que proíbe, dando um exemplo ligado a cores.', 0.4, 'ND (Sem Derivações) permite só o arquivo exato original e proíbe editar, cortar ou alterar as cores, por exemplo trocar a cor de um ícone.', 'Nota cheia: diz o que permite (arquivo exato) e o que proíbe (editar, cortar ou mudar cores), com exemplo de cor. Metade: diz o que proíbe sem falar do que permite, ou vice-versa. Zero: em branco ou errado.'),
      (v_atividade, 12, 1, 'Relacione a sigla BY-NC-SA aos seus três termos.', 0.2, 'BY = citar o autor; NC = sem vendas (não comercial); SA = espelhar os termos (a obra derivada usa a mesma licença).', 'Nota cheia: relaciona as três siglas aos três termos corretos. Metade: relaciona duas siglas corretamente. Zero: em branco ou errado.'),
      (v_atividade, 12, 2, 'Explique a consequência do bloco SA para o projeto resultante.', 0.4, 'O bloco SA obriga que o projeto resultante (a adaptação) também seja licenciado como CC BY-NC-SA.', 'Nota cheia: diz que o projeto derivado precisa ter a mesma licença (BY-NC-SA). Metade: diz que é preciso compartilhar, sem indicar a mesma licença. Zero: em branco ou errado.'),
      (v_atividade, 12, 3, 'Diga se é possível monetizar o aplicativo com essa ilustração, justificando.', 0.4, 'Não. O bloco NC proíbe monetizar o aplicativo com essa ilustração, pois o app pago tem finalidade comercial.', 'Nota cheia: responde "não" e justifica pelo NC (monetização proibida). Metade: responde "não" sem justificar, ou justifica sem o NC. Zero: responde "sim" ou está em branco.'),
      (v_atividade, 13, 1, 'Diga o que a cláusula ND impede no design.', 0.2, 'A cláusula ND impede modificar a obra no design: não pode mudar a cor nem recortar a peça.', 'Nota cheia: diz que impede mudar a cor e recortar a peça. Metade: cita só um dos dois impedimentos. Zero: em branco ou errado.'),
      (v_atividade, 13, 2, 'Explique por que, em produtos pagos, o recurso precisa permitir explicitamente o uso comercial.', 0.4, 'Porque, em produtos pagos, o recurso precisa permitir explicitamente o uso comercial; sem isso, o uso no app pago não é permitido.', 'Nota cheia: liga o produto pago à necessidade de permissão explícita de uso comercial. Metade: diz que é preciso permissão, sem ligar ao produto pago. Zero: em branco ou errado.'),
      (v_atividade, 13, 3, 'Indique a conduta que você adotaria para resolver a necessidade de mudar a cor, sem violar a licença.', 0.4, 'Não alterar o recurso com ND: pedir autorização formal ao criador ou usar um recurso com licença que permita derivações e uso comercial, ou ajustar a cor por meio do próprio tema do sistema, sem editar o arquivo.', 'Nota cheia: indica uma conduta que não altera o arquivo com ND (pedir autorização, trocar por recurso permissivo ou usar outro meio). Metade: indica uma conduta que altera o arquivo sem perceber a restrição, ou resposta genérica. Zero: propõe alterar a cor do arquivo com ND, ou está em branco.'),
      (v_atividade, 14, 1, 'Responda se a arte pode ser usada no aplicativo pago.', 0.2, 'Não. A arte CC BY-NC 4.0 não pode ser usada no aplicativo pago.', 'Nota cheia: responde "não" para o uso no app pago. Metade: responde "não" sem clareza. Zero: responde "sim" ou está em branco.'),
      (v_atividade, 14, 2, 'Justifique sua resposta com a cláusula NC.', 0.4, 'A cláusula NC proíbe qualquer finalidade comercial ou de lucro financeiro, e um app pago tem finalidade comercial.', 'Nota cheia: justifica pela cláusula NC e pela finalidade comercial do app pago. Metade: cita o NC sem ligar ao app pago. Zero: em branco ou errado.'),
      (v_atividade, 14, 3, 'Indique uma alternativa segura, com licença permissiva, citando um exemplo da aula.', 0.4, 'Usar um recurso com licença permissiva, por exemplo o ícone Lucide (licença ISC) ou a fonte Inter (SIL Open Font License), que permitem uso comercial.', 'Nota cheia: indica uma alternativa permissiva e cita um exemplo da aula (Lucide, Inter, Google Fonts, Unsplash ou Pexels com termos próprios). Metade: indica uma alternativa permissiva sem exemplo da aula. Zero: indica outra arte com NC ou está em branco.'),
      (v_atividade, 15, 1, 'Liste as quatro etapas do procedimento de checagem de fontes.', 0.2, 'As quatro etapas são: 1 Ler o EULA; 2 Ver permissão; 3 Baixar o txt; 4 Registrar.', 'Nota cheia: lista as quatro etapas na ordem. Metade: lista três etapas corretas. Zero: em branco ou etapas que não estão na aula.'),
      (v_atividade, 15, 2, 'Explique o que deve ser confirmado na etapa "Ver permissão".', 0.4, 'Na etapa "Ver permissão", deve-se conferir se a licença autoriza o uso como webfont ou em app.', 'Nota cheia: diz que é conferido se a licença autoriza webfont ou app. Metade: diz que é conferida a permissão, sem o tipo de uso. Zero: em branco ou errado.'),
      (v_atividade, 15, 3, 'Explique o que deve ser anotado na etapa "Registrar".', 0.4, 'Na etapa "Registrar", anota-se o nome do criador e o tipo de licença.', 'Nota cheia: cita nome do criador e tipo de licença. Metade: cita apenas um dos dois. Zero: em branco ou errado.'),
      (v_atividade, 16, 1, 'Cite os três itens que compõem a trilha de auditoria.', 0.2, 'Os três itens são: URL da fonte original; data do download (print com data); termo de autorização (cópia em PDF dos termos da plataforma).', 'Nota cheia: cita os três itens. Metade: cita dois itens corretos. Zero: em branco ou errado.'),
      (v_atividade, 16, 2, 'Explique por que um print da tela com data comprova os termos vigentes no momento do download.', 0.4, 'O print com data mostra os termos que estavam valendo no momento do download, o que comprova a licença vigente naquele dia.', 'Nota cheia: liga o print com data aos termos vigentes no momento do download. Metade: diz que o print serve de prova, sem a ideia de termos vigentes. Zero: em branco ou errado.'),
      (v_atividade, 16, 3, 'Explique como a trilha protege a agência e o cliente.', 0.4, 'A trilha comprova de onde veio a imagem e em quais termos foi baixada, protegendo a agência e o cliente em caso de questionamento.', 'Nota cheia: diz que a trilha comprova origem e termos e protege agência e cliente. Metade: diz que protege, sem explicar como. Zero: em branco ou fora do tema.'),
      (v_atividade, 17, 1, 'Diga o que o INPI registra, segundo a aula.', 0.2, 'O INPI registra marcas, programas de computador e desenhos industriais (aspecto ornamental de produtos e ícones tridimensionais).', 'Nota cheia: cita marcas, programas de computador e desenhos industriais. Metade: cita dois dos três. Zero: em branco ou errado.'),
      (v_atividade, 17, 2, 'Diga o que a Biblioteca Nacional registra, segundo a aula.', 0.4, 'A Biblioteca Nacional registra o direito autoral de obras visuais e artísticas, como ilustrações, personagens originais, identidades completas e manuais de marca.', 'Nota cheia: diz que registra direito autoral de obras visuais e artísticas, com exemplo. Metade: diz que registra direito autoral, sem os tipos de obra. Zero: em branco ou errado.'),
      (v_atividade, 17, 3, 'Explique a diferença entre os dois órgãos quanto ao tipo de criação protegida.', 0.4, 'O INPI cuida da propriedade industrial (marcas, programas e desenhos industriais), e a Biblioteca Nacional cuida das obras visuais e artísticas do direito autoral.', 'Nota cheia: diferencia os dois órgãos pelo tipo de criação. Metade: diferencia só de forma vaga. Zero: em branco ou errado.'),
      (v_atividade, 18, 1, 'Liste os elementos que, segundo a aula, compõem um design system completo.', 0.2, 'Logotipos, paletas cromáticas exclusivas e componentes de interface estilizados.', 'Nota cheia: cita os três elementos. Metade: cita dois. Zero: em branco ou errado.'),
      (v_atividade, 18, 2, 'Explique o que o registro de marca e do código do software garante.', 0.4, 'O registro de marca e do código do software garante exclusividade de mercado, impedindo que concorrentes copiem a identidade e o programa.', 'Nota cheia: diz que garante exclusividade de mercado e impede cópia de marca e código. Metade: cita o registro sem o efeito de exclusividade. Zero: em branco ou errado.'),
      (v_atividade, 18, 3, 'Explique como a exclusividade visual protege o usuário final.', 0.4, 'A exclusividade visual impede que concorrentes copiem a experiência, evitando que enganem o usuário final com uma interface parecida.', 'Nota cheia: liga a exclusividade a não enganar o usuário final. Metade: diz que protege a marca, sem ligar ao usuário final. Zero: em branco ou fora do tema.'),
      (v_atividade, 19, 1, 'Liste as colunas da ficha de licenças.', 0.2, 'A ficha tem as colunas: Recurso/Tipo, Autor/Criador, Licença Exata e Uso Comercial? (com link de origem).', 'Nota cheia: lista as quatro colunas (ou as três principais, com o link). Metade: lista duas colunas corretas. Zero: em branco ou errado.'),
      (v_atividade, 19, 2, 'Explique o que cada recurso do mock-up precisa ter registrado na ficha.', 0.4, 'Cada recurso (fonte, ícones, foto de perfil) precisa de uma linha com autor, link e licença exata, além da informação de uso comercial.', 'Nota cheia: diz que cada recurso tem linha com link e licença exata, citando os três recursos do mock-up ou o conceito geral. Metade: diz que cada recurso deve ser registrado, sem o link ou a licença exata. Zero: em branco ou errado.'),
      (v_atividade, 19, 3, 'Explique por que a ficha compõe a entrega e serve de garantia antes da codificação.', 0.4, 'A ficha compõe a entrega oficial e serve de garantia jurídica antes do envio para a codificação, evitando problemas depois.', 'Nota cheia: diz que é parte da entrega e garantia jurídica antes da codificação. Metade: diz que é entrega ou garantia, sem o momento antes da codificação. Zero: em branco ou errado.'),
      (v_atividade, 20, 1, 'Liste os três passos da auditoria do colega.', 0.2, 'Os três passos são: receber o mock-up; validar os links; emitir o parecer (apontando ativos seguros ou pendências).', 'Nota cheia: lista os três passos na ordem. Metade: lista dois passos corretos. Zero: em branco ou errado.'),
      (v_atividade, 20, 2, 'Explique os três critérios de análise: conformidade total, atribuição pendente e risco de infração.', 0.4, 'Conformidade total: recurso com licença permissiva comprovada ou autoria própria. Atribuição pendente: CC BY sem crédito no app. Risco de infração: recurso sem procedência clara ou com NC/ND em app comercial.', 'Nota cheia: explica os três critérios com a ideia de cada um. Metade: explica dois critérios corretos. Zero: em branco ou errado.'),
      (v_atividade, 20, 3, 'Explique como validar os links da ficha e como redigir o parecer de forma amável.', 0.4, 'Validar os links testando se a URL abre a licença real; redigir o parecer com respeito e colaboração, apontando os pontos de risco de forma amável.', 'Nota cheia: explica a validação de links (abrir a licença real) e a redação amável e colaborativa do parecer. Metade: explica só um dos dois. Zero: em branco ou fora do tema.');
